        else:
            grp = df_clean.groupby('plan')[metric].mean()
        result['segments'].append({
            'segment_column': 'plan',
            'metric_column': metric,
            'aggregation': 'sum' if metric != 'churned' else 'mean',
            'label': None,
            'results': [{'name': str(k), 'value': round(float(v), 4)} for k, v in grp.items()]
        })

    # Churn rate by plan
    churn_rate = df_clean.groupby('plan')['churned'].mean()
    result['segments'].append({
        'segment_column': 'plan',
        'metric_column': 'churned',
        'aggregation': 'ratio',
        'label': 'churn_rate',
        'results': [{'name': str(k), 'value': round(float(v), 4)} for k, v in churn_rate.items()]
    })
except Exception as e:
    result['assumptions'].append(f"Segmentation partial: {e}")

try:
    # Anomaly detection on metric columns
    skip_cols = set()
    anomaly_records = []
    for col in ['mrr', 'seats', 'active_users']:
        s = latest_snap[col].dropna()
        if s.nunique() < 5:
            continue
        skew = float(s.skew())
        if abs(skew) > 2:
            shift = max(0, -s.min())
            s_t = np.log1p(s + shift)
        else:
            s_t = s.copy()
            shift = 0
        q1, q3 = s_t.quantile(0.25), s_t.quantile(0.75)
        iqr = q3 - q1
        lo_ext = q1 - 3 * iqr
        hi_ext = q3 + 3 * iqr
        flagged = s_t[(s_t < lo_ext) | (s_t > hi_ext)]
        if len(flagged) / len(s_t) > 0.05:
            anomaly_records.append({
                'column': col, 'row_index': None, 'value': None,
                'expected_range': 'heavy-tailed distribution',
                'severity': 'low',
                'explanation': f"{col} is heavy-tailed; extreme values are natural, not anomalies"
            })
            continue
        if abs(skew) > 2:
            lo_orig = np.expm1(lo_ext) - shift
            hi_orig = np.expm1(hi_ext) - shift
        else:
            lo_orig = lo_ext
            hi_orig = hi_ext
        exp_range = f"[{lo_orig:.2f}, {hi_orig:.2f}]"
        for idx in flagged.index:
            orig_val = float(latest_snap.loc[idx, col])
            t_val = float(s_t.loc[idx])
            if t_val > q3 + 5 * iqr:
                sev = 'critical'
            elif t_val > q3 + 4 * iqr:
                sev = 'high'
            else:
                sev = 'medium'
            anomaly_records.append({
                'column': col, 'row_index': int(idx), 'value': orig_val,
                'expected_range': exp_range, 'severity': sev,
                'explanation': f"{col} value {orig_val:.2f} lies outside expected range {exp_range}"
            })
    anomaly_records = anomaly_records[:25]
    result['anomalies'].extend(anomaly_records)
except Exception as e:
    result['assumptions'].append(f"Anomaly partial: {e}")

try:
    # Trends: MoM for mrr (sum of latest snapshot per month), seats, active_users
    monthly_mrr = df_clean.sort_values('month').groupby(['month', 'account_id'])['mrr'].last().reset_index()
    monthly_mrr = monthly_mrr.groupby('month')['mrr'].sum().reset_index().sort_values('month')
    if len(monthly_mrr) >= 2:
        pct = float((monthly_mrr['mrr'].iloc[-1] - monthly_mrr['mrr'].iloc[-2]) / monthly_mrr['mrr'].iloc[-2] * 100)
        direction = 'up' if pct > 0.5 else ('down' if pct < -0.5 else 'flat')
        result['trends'].append({'column': 'mrr', 'period': 'MoM', 'direction': direction, 'pct_change': round(pct, 4), 'segment': None})

    for col in ['seats', 'active_users']:
        monthly_col = df_clean.sort_values('month').groupby(['month', 'account_id'])[col].last().reset_index()
        monthly_col = monthly_col.groupby('month')[col].sum().reset_index().sort_values('month')
        if len(monthly_col) >= 2:
            pct = float((monthly_col[col].iloc[-1] - monthly_col[col].iloc[-2]) / monthly_col[col].iloc[-2] * 100)
            direction = 'up' if pct > 0.5 else ('down' if pct < -0.5 else 'flat')
            result['trends'].append({'column': col, 'period': 'MoM', 'direction': direction, 'pct_change': round(pct, 4), 'segment': None})

    # Churned: monthly mean
    monthly_churn = df_clean.groupby('month')['churned'].mean().reset_index().sort_values('month')
    if len(monthly_churn) >= 2:
        pct = float((monthly_churn['churned'].iloc[-1] - monthly_churn['churned'].iloc[-2]) / (monthly_churn['churned'].iloc[-2] + 1e-9) * 100)
        direction = 'up' if pct > 0.5 else ('down' if pct < -0.5 else 'flat')
        result['trends'].append({'column': 'churned', 'period': 'MoM', 'direction': direction, 'pct_change': round(pct, 4), 'segment': None})
except Exception as e:
    result['assumptions'].append(f"Trend partial: {e}")

try:
    # Forecasting: simple linear extrapolation of MRR for next 3 months
    monthly_mrr2 = df_clean.sort_values('month').groupby(['month', 'account_id'])['mrr'].last().reset_index()
    monthly_mrr2 = monthly_mrr2.groupby('month')['mrr'].sum().reset_index().sort_values('month')
    monthly_mrr2['t'] = np.arange(len(monthly_mrr2))
    slope, intercept, _, _, _ = stats.linregress(monthly_mrr2['t'], monthly_mrr2['mrr'])
    last_t = monthly_mrr2['t'].iloc[-1]
    last_month = monthly_mrr2['month'].iloc[-1]
    for i in range(1, 4):
        future_month = last_month + pd.DateOffset(months=i)
        pred = intercept + slope * (last_t + i)
        result['forecast_points'].append({'period': future_month.strftime('%Y-%m'), 'value': round(float(pred), 2)})
except Exception as e:
    result['assumptions'].append(f"Forecast partial: {e}")

result['assumptions'] = result['assumptions'][:5]
result['assumptions'].insert(0, "Level metrics (mrr, seats, active_users) use last snapshot per account_id per month before aggregation.")
result['assumptions'] = result['assumptions'][:5]
